/* ==========================================================================
   CSS Variables for Dark Theme
   ========================================================================== */
:root {
    /* Colors */
    --color-bg-base: #121212; /* Very dark gray/black */
    --color-bg-surface: #1e1e1e; /* Slightly lighter for cards/surfaces */
    --color-bg-surface-alt: #2c2c2c;

    --color-text-primary: #f5f5f5; /* Off-white for high contrast readable text */
    --color-text-secondary: #b3b3b3; /* Light gray for secondary text */

    --color-accent-primary: #4db8ff; /* High contrast light blue for buttons/links */
    --color-accent-primary-hover: #3a8ccc;
    --color-accent-secondary: #ff7597; /* Soft pink for alerts/wishlists */

    --color-border: #333333;

    /* Typography */
    --font-family-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
    --font-family-heading: "Playfair Display", Georgia, serif;

    /* Spacing */
    --space-xs: 0.5rem;
    --space-sm: 1rem;
    --space-md: 1.5rem;
    --space-lg: 2rem;
    --space-xl: 3rem;
    --space-xxl: 5rem;

    /* Transitions */
    --transition-fast: 0.2s ease;
    --transition-normal: 0.3s ease;

    /* Shadows */
    --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.5);
    --shadow-md: 0 4px 8px rgba(0, 0, 0, 0.5);
    --shadow-focus: 0 0 0 3px var(--color-accent-primary);
}

/* ==========================================================================
   Reset & Base Styles
   ========================================================================== */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    scroll-behavior: smooth;
    font-size: 16px;
}

body {
    font-family: var(--font-family-base);
    background-color: var(--color-bg-base);
    color: var(--color-text-primary);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-family-heading);
    line-height: 1.2;
    margin-bottom: var(--space-sm);
    font-weight: 700;
}

