/**
 * Main JavaScript file for Luxe Retail Home Page
 */

document.addEventListener('DOMContentLoaded', () => {
    initMobileMenu();
    initWishlistButtons();
    initNewsletterForm();
    initSmoothScrolling();
});

/**
 * Initializes the mobile menu toggle functionality.
 * Handles ARIA attributes for accessibility.
 */
function initMobileMenu() {
    const menuToggle = document.getElementById('menu-toggle');
    const mainMenu = document.getElementById('main-menu');

    if (!menuToggle || !mainMenu) return;

    menuToggle.addEventListener('click', () => {
        const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';

        // Toggle state
        menuToggle.setAttribute('aria-expanded', !isExpanded);
        mainMenu.classList.toggle('active');

        // Change icon based on state
        if (!isExpanded) {
            // Change to X icon
            menuToggle.innerHTML = `
                <span class="sr-only">Close Menu</span>
                <svg aria-hidden="true" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <line x1="18" y1="6" x2="6" y2="18"></line>
                    <line x1="6" y1="6" x2="18" y2="18"></line>
                </svg>
            `;
        } else {
            // Change to Hamburger icon
            menuToggle.innerHTML = `
                <span class="sr-only">Toggle Menu</span>
                <svg aria-hidden="true" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <line x1="3" y1="12" x2="21" y2="12"></line>
                    <line x1="3" y1="6" x2="21" y2="6"></line>
                    <line x1="3" y1="18" x2="21" y2="18"></line>
                </svg>
            `;
        }
    });

    // Close menu when pressing Escape
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && mainMenu.classList.contains('active')) {
            menuToggle.click();
            menuToggle.focus();
        }
    });
}

/**
 * Initializes wishlist buttons toggle functionality.
 */
function initWishlistButtons() {
    const wishlistBtns = document.querySelectorAll('.wishlist-btn');

    wishlistBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault(); // Prevent navigating if wrapped in a link
            e.stopPropagation(); // Prevent triggering click on parent container

            const isActive = btn.classList.contains('active');
            const productName = btn.getAttribute('aria-label').replace('Add ', '').replace(' to wishlist', '').replace('Remove ', '');

            if (isActive) {
                btn.classList.remove('active');
                btn.setAttribute('aria-label', `Add ${productName} to wishlist`);
                btn.title = 'Add to wishlist';
            } else {
                btn.classList.add('active');
                btn.setAttribute('aria-label', `Remove ${productName} from wishlist`);
                btn.title = 'Remove from wishlist';
            }
        });
    });
}

/**
 * Initializes the newsletter form submission.
 */
function initNewsletterForm() {
    const form = document.getElementById('newsletter-form');
    const messageContainer = document.getElementById('newsletter-message');

    if (!form || !messageContainer) return;

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const emailInput = document.getElementById('email');
        const email = emailInput.value;

        // Basic validation
        if (email && email.includes('@')) {
            // Simulate API call
            const submitBtn = form.querySelector('button[type="submit"]');
            const originalText = submitBtn.textContent;

            submitBtn.disabled = true;
            submitBtn.textContent = 'Submitting...';

            setTimeout(() => {
                // Show success message
                messageContainer.textContent = 'Thank you for subscribing!';
                messageContainer.classList.remove('sr-only');
                messageContainer.style.display = 'block';
                messageContainer.style.marginTop = '1rem';
                messageContainer.style.color = 'var(--color-accent-primary)';

                // Reset form
                form.reset();
                submitBtn.disabled = false;
                submitBtn.textContent = originalText;

                // Hide message after a few seconds
                setTimeout(() => {
                    messageContainer.classList.add('sr-only');
                    messageContainer.style.display = '';
                }, 5000);
            }, 1000);
        }
    });
}

/**
 * Initializes smooth scrolling for anchor links to improve keyboard focus behavior.
 */
function initSmoothScrolling() {
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function(e) {
            const targetId = this.getAttribute('href');

            if (targetId === '#') return;

            const targetElement = document.querySelector(targetId);

            if (targetElement) {
                e.preventDefault();
                targetElement.scrollIntoView({
                    behavior: 'smooth'
                });

                // Update focus for accessibility
                targetElement.setAttribute('tabindex', '-1');
                targetElement.focus({ preventScroll: true });

                // Optional: Update URL without jumping
                history.pushState(null, null, targetId);
            }
        });
    });
}

